//! The glue of the `lora` component (43) for the module that hosts it, generated by `tools/gen_vtables.py` from `modules/mod_lora/API.md`; do not edit.
//!
//! [`Api`] is what the module implements. [`dispatch`] serves a request (a method number and the fields map: the runtime has parsed the
//! envelope) and [`table`] is the module's vtable for other modules, whose functions enter the allocator context of the module (`Ctx`).
#![allow(clippy::all, dead_code, unused_imports)]
use core::ffi::{c_int, c_void};
use xip_abi::{Lora, CallView, Hw, Host, ERR_ARG, ERR_SIZE, ERR_UNSUPPORTED, };

pub const COMPONENT: i32 = 43;

/// What the module implements. Every method returns `Err(code)` with a negative `ERR_*`.
pub trait Api {
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): NAN calls this to replace or restore its LoRa/FSK receive role without racing a queued module stop. The borrowed start-format request is validated before stopping existing work; only rx, fsk without payload, and idle are accepted. Success admits asynchronous board initialization, not reception.
    fn configure(&mut self, hw: &Hw, record: *const u8, len: usize) -> Result<(), i32>;
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): NAN calls this before coordinated sleep or explicit radio off to synchronously cancel radio work and release SPI, IRQ and power. The mapped module remains callable until explicitly stopped.
    fn suspend(&mut self, hw: &Hw) -> Result<(), i32>;
}

/// Serve method `method` with the request `fields`; the response map goes to `out`. Returns its length. An unknown method is `ERR_UNSUPPORTED`.
pub fn dispatch<T: Api>(t: &mut T, hw: &Hw, method: i32, fields: &[u8], out: &mut [u8]) -> Result<usize, i32> {
    let _ = (t, hw, fields, out);
    match method {
        _ => Err(ERR_UNSUPPORTED),
    }
}

/// The first argument of every function of the module's table: the host table and the module's state, both valid while the module runs.
#[repr(C)]
pub struct Ctx {
    pub host: *const Host,
    pub state: *mut u8,
}

/// Run `body` in the allocator context of the module (the runtime's thunk has taken the module's lock).
unsafe fn within<T: Api>(ctx: *mut c_void, body: impl FnOnce(&mut T, &Hw) -> Result<(), i32>) -> c_int {
    let ctx = &*(ctx as *const Ctx);
    let Some(hw) = Hw::new(ctx.host) else { return ERR_ARG };
    let saved = xip_abi::heap::enter(ctx.host);
    let rc = match body(&mut *(ctx.state as *mut T), &hw) { Ok(()) => 0, Err(rc) => rc };
    xip_abi::heap::leave(saved);
    rc
}

unsafe extern "C" fn v_configure<T: Api>(ctx: *mut c_void, record: *const u8, len: usize) -> c_int {
    within::<T>(ctx, |t, hw| t.configure(hw, record, len))
}
unsafe extern "C" fn v_suspend<T: Api>(ctx: *mut c_void) -> c_int {
    within::<T>(ctx, |t, hw| t.suspend(hw))
}

/// The module's table of the `lora` component and the context its functions take: a part of the module's state block. The table is built
/// when the module answers `HOST_TABLE`, not as a constant: the function addresses of a position-independent image (ESP32-C6) exist only at run time.
#[repr(C)]
pub struct Hosted {
    pub ctx: Ctx,
    pub table: Lora,
}
impl Default for Hosted {
    /// All zero: no table yet (the state block of a module starts zeroed).
    fn default() -> Self {
        unsafe { core::mem::zeroed() }
    }
}

/// Answer `HOST_TABLE` for this component with the module's table, whose functions call `T` in the module's allocator context, and the context
/// they take. `hosted` points into the module's state block (it must stay valid while the module runs) and `state` is that block as `T`.
pub fn provide<T: Api>(hw: &Hw, call: &CallView, hosted: *mut Hosted, state: *mut T) -> i32 {
    unsafe {
        (*hosted).ctx = Ctx { host: hw.as_ptr(), state: state.cast() };
        (*hosted).table = Lora {
            version: 1,
            size: core::mem::size_of::<Lora>() as u32,
            configure: Some(v_configure::<T>),
            suspend: Some(v_suspend::<T>),
        };
        hw.provide_table(call, core::ptr::addr_of!((*hosted).table).cast(), core::ptr::addr_of_mut!((*hosted).ctx).cast())
    }
}
